package ActionsEvents_1SignalTriggers {
    private import ScalarValues::*; 
    private import SysML::*;
    /* Wrapped Snippet (Action Context) */
    action def Main {
        accept  start  :  StartSignal ;
        accept  msg  :  Message  via  p1 ;
        doc  /* Wait for signal */
    }

    view ExposeExample {
        expose Main;
    }
}

package ActionsEvents_2ChangeTriggers {
    private import ScalarValues::*; 
    private import SysML::*;
    /* Wrapped Snippet (Action Context) */
    action def Main {
        accept  when  temperature > 100 ;
        accept  when  tank.full ;
        doc  /* Wait for condition */
    }

    view ExposeExample {
        expose Main;
    }
}

package ActionsEvents_3TimeTriggers {
    private import ScalarValues::*; 
    private import SysML::*;
    /* Wrapped Snippet (Action Context) */
    action def Main {
        accept  at  '12:00:00' ;
        accept  after  10 [s] ;
        doc  /* Absolute/Relative time */
    }

    view ExposeExample {
        expose Main;
    }
}

package ActionsEvents_4SendAction {
    private import ScalarValues::*; 
    private import SysML::*;
    /* Wrapped Snippet (Action Context) */
    action def Main {
        send  StartSignal ( ) ;
        send  Cmd ( val = 42 )  to  server ;
        send  msg  via  pOut ;
    }

    view ExposeExample {
        expose Main;
    }
}

package ActionsEvents_5AdvancedSend {
    private import ScalarValues::*; 
    private import SysML::*;
    /* Wrapped Snippet (Action Context) */
    action def Main {
        action  prepareAndSend  {
           action  s  :  SendAction  {
              in  payload  =  42 ;
              out  result ;
           }
        }
    }

    view ExposeExample {
        expose Main;
    }
}
